// Parse the HTML email to extract 470 application links
const htmlContent = $input.item.json.html || $input.item.json.text;

// Extract all 470 application numbers and create structured data
const regex = /(\d{9})\s+([^\n]+?)\s+(FL|TX)\s+(\d+)\s+Basic Maintenance/g;
const leads = [];
let match;

while ((match = regex.exec(htmlContent)) !== null) {
  const appNumber = match[1];
  const applicantName = match[2].trim();
  const state = match[3];
  const sites = match[4];

  // Extract product information for this application
  const productRegex = new RegExp(
    appNumber + '[\\s\\S]*?(?=(\\d{9}|$))',
    'g'
  );
  const appSection = htmlContent.match(productRegex);
  let products = [];

  if (appSection && appSection[0]) {
    const productMatches = appSection[0].matchAll(
      /(Wireless Access Points|Switches|Routers|Wireless Controllers)[^\n]*?-\s*([^(]+)\((\d+)\)/g
    );

    for (const pm of productMatches) {
      products.push({
        type: pm[1].trim(),
        manufacturer: pm[2].trim(),
        quantity: parseInt(pm[3])
      });
    }
  }

  leads.push({
    applicationNumber: appNumber,
    applicantName: applicantName,
    state: state,
    sites: parseInt(sites),
    products: products,
    url: `https://www.usac.org/e-rate/applicant-process/before-you-begin/learn-about-form-470/`,
    // The actual URL would be constructed from the application number
    applicationUrl: `https://data.usac.org/publicreports/Forms/Form470Rfp/Index?FundingYear=2025&ApplicationNumber=${appNumber}`,
    datePosted: new Date().toISOString().split('T')[0],
    status: 'new'
  });
}

// Return each lead as a separate item for processing
return leads.map(lead => ({ json: lead }));
